INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(250, 'brain', '/breɪn/', 'noun', '{"zh-TW":["大腦；腦力","大腦；頭腦"],"en":["the organ of thought","intelligence","the organ inside the head that controls the body"]}', NULL, 'brainstorm / brain drain; brain storm / brain power', '[{"en":"Let''s brainstorm some ideas.","zh-TW":"讓我們腦力激盪一些點子。"},{"en":"Brain drain is a serious issue.","zh-TW":"人才外流是嚴重的問題。"},{"en":"The brain controls all body functions.","zh-TW":"大腦控制所有的身體功能。"},{"en":"Use your brain!","zh-TW":"動動腦筋！"}]', '{"noun":"brain","adjective":"brainy","verb":"brainstorm"}', NULL, 2, 250),
(251, 'branch', '/brɑːntʃ/', 'noun', '{"zh-TW":["分公司；分支"],"en":["a division of a larger organization","a local office of a company"]}', '{"root":{"text":"branch","meaning":"arm/limb (樹枝/手臂)"},"logic":"從主體延伸出去的，即「分支」。"}', 'branch office / branch manager / open a branch', '[{"en":"The bank has over 200 branches nationwide.","zh-TW":"該銀行在全國有超過200家分行。"},{"en":"We plan to open a new branch in Taipei.","zh-TW":"我們計劃在台北開設新分公司。"}]', NULL, NULL, 2, 251),
(252, 'brand', '/brænd/', 'noun', '{"zh-TW":["品牌","品牌；商標"],"en":["a type of product made by a particular company"]}', '{"root":{"text":"brand","meaning":"burn/mark (燒/標記)"},"logic":"燒印標記以識別，即「品牌」。"}', 'brand awareness / brand image / brand loyalty; brand name / brand loyalty / brand awareness', '[{"en":"Building a strong brand takes years of effort.","zh-TW":"建立強大的品牌需要多年努力。"},{"en":"The new campaign increased brand awareness by 30%.","zh-TW":"新活動將品牌知名度提高了30%。"},{"en":"This brand is known for its high quality.","zh-TW":"這個品牌以高品質聞名。"},{"en":"They are trying to build brand awareness.","zh-TW":"他們正努力建立品牌知名度。"}]', '{"noun":"branding","verb":"brand","adjective":"branded"}', NULL, 2, 252),
(253, 'brave', '/breɪv/', 'adjective', '{"zh-TW":["勇敢的"],"en":["ready to face danger"]}', NULL, 'brave enough / brave face', '[{"en":"She was brave to speak up.","zh-TW":"她勇敢地站出來發言。"},{"en":"The brave soldier saved his team.","zh-TW":"勇敢的士兵拯救了他的隊伍。"}]', '{"noun":"bravery","adverb":"bravely"}', NULL, 2, 253),
(254, 'breach', '/briːtʃ/', 'noun', '{"zh-TW":["違反；破壞"],"en":["a failure to observe a law, agreement, or code of conduct"]}', '{"root":{"text":"breach","meaning":"break (打破)"},"logic":"打破規則，即「違反」。"}', 'breach of contract / security breach / data breach', '[{"en":"The lawsuit alleges a breach of contract.","zh-TW":"訴訟指控違反合約。"},{"en":"A data breach exposed customer information.","zh-TW":"資料外洩暴露了客戶資訊。"}]', NULL, NULL, 2, 254),
(255, 'bread', '/brɛd/', 'noun', '{"zh-TW":["麵包"],"en":["food made from flour and water"]}', NULL, 'slice of bread / bread and butter', '[{"en":"I''d like some bread, please.","zh-TW":"請給我一些麵包。"},{"en":"Teaching is her bread and butter.","zh-TW":"教書是她的生計。"}]', NULL, NULL, 2, 255),
(256, 'break', '/breɪk/', 'noun', '{"zh-TW":["休息；打破","打破；休息"],"en":["a pause in work","to separate into pieces"]}', NULL, 'take a break / break down; break down / take a break', '[{"en":"Let''s take a 15-minute break.","zh-TW":"我們休息15分鐘吧。"},{"en":"The machine broke down yesterday.","zh-TW":"機器昨天故障了。"},{"en":"Be careful not to break it.","zh-TW":"小心別打破了。"},{"en":"Let''s take a short break.","zh-TW":"讓我們休息一下。"}]', '{"verb":"break","noun":"break","noun2":"breakdown","adjective":"breakable"}', NULL, 2, 256),
(257, 'breakthrough', '/ˈbreɪkθruː/', 'noun', '{"zh-TW":["突破"],"en":["a sudden important development or discovery"]}', '{"root":{"text":"break","meaning":"break (打破)"},"suffix":{"text":"through","meaning":"through (穿過)"},"logic":"打破穿過障礙，即「突破」。"}', 'major breakthrough / technological breakthrough', '[{"en":"The research team achieved a major breakthrough.","zh-TW":"研究團隊取得了重大突破。"},{"en":"This technology represents a breakthrough in AI.","zh-TW":"這項技術代表了人工智慧的突破。"}]', NULL, NULL, 4, 257),
(258, 'breath', '/brɛθ/', 'noun', '{"zh-TW":["呼吸；氣息"],"en":["the air that goes in and out of lungs"]}', NULL, 'take a breath / out of breath', '[{"en":"Take a deep breath.","zh-TW":"深呼吸。"},{"en":"She was out of breath from running.","zh-TW":"她跑得上氣不接下氣。"}]', '{"verb":"breathe","adjective":"breathless"}', NULL, 2, 258),
(259, 'breeze', '/briːz/', 'noun', '{"zh-TW":["微風"],"en":["a gentle wind"]}', '{"root":{"text":"breeze","meaning":"light wind (輕風)"},"logic":"指輕柔的風。"}', 'a gentle breeze / sea breeze', '[{"en":"A cool breeze blew in from the ocean.","zh-TW":"一陣涼爽的海風吹來。"},{"en":"The curtains moved gently in the breeze.","zh-TW":"窗簾在微風中輕輕飄動。"}]', '{"adjective":"breezy"}', NULL, 2, 259),
(260, 'bridge', '/brɪdʒ/', 'noun', '{"zh-TW":["橋；橋梁"],"en":["a structure over a river or road"]}', NULL, 'build a bridge / bridge the gap', '[{"en":"They built a new bridge over the river.","zh-TW":"他們在河上建了一座新橋。"},{"en":"Education bridges the gap.","zh-TW":"教育彌合了差距。"}]', NULL, NULL, 2, 260),
(261, 'brief', '/briːf/', 'adjective', '{"zh-TW":["簡短的；簡報"],"en":["lasting only a short time","a summary of facts or instructions"]}', '{"root":{"text":"brev","meaning":"short (短)"},"logic":"短的，即「簡短的」。"}', 'brief description / brief meeting / in brief', '[{"en":"Please provide a brief summary of your proposal.","zh-TW":"請提供您提案的簡短摘要。"},{"en":"The manager gave the team a brief on the new project.","zh-TW":"經理向團隊簡報了新專案。"}]', '{"adverb":"briefly","noun":"briefing"}', NULL, 2, 261),
(262, 'bright', '/braɪt/', 'adjective', '{"zh-TW":["明亮的；聰明的"],"en":["giving out much light; intelligent"]}', NULL, 'bright future / bright idea', '[{"en":"The sun is very bright today.","zh-TW":"今天太陽很亮。"},{"en":"She has a bright future ahead.","zh-TW":"她前途光明。"}]', '{"noun":"brightness","adverb":"brightly","verb":"brighten"}', NULL, 2, 262),
(263, 'brilliant', '/ˈbrɪliənt/', 'adjective', '{"zh-TW":["傑出的；明亮的"],"en":["exceptionally clever or talented","very bright"]}', '{"root":{"text":"brill","meaning":"shine (閃耀)"},"suffix":{"text":"-iant","meaning":"being (…的)"},"logic":"閃耀著光芒的，即「傑出的」。"}', 'brilliant idea / brilliant career / brilliant color', '[{"en":"She had a brilliant idea for the project.","zh-TW":"她對這個專案有個絕妙的點子。"},{"en":"He has had a brilliant career in science.","zh-TW":"他在科學領域有卓越的職業生涯。"}]', '{"noun":"brilliance","adverb":"brilliantly"}', NULL, 3, 263),
(264, 'bring', '/brɪŋ/', 'verb', '{"zh-TW":["帶來；引起"],"en":["to carry to a place","to cause","to carry something to a place"]}', NULL, 'bring about / bring up; bring up / bring about', '[{"en":"Please bring your laptop to the meeting.","zh-TW":"請帶你的筆電來開會。"},{"en":"The merger brought about many changes.","zh-TW":"合併帶來了許多變化。"},{"en":"Bring your umbrella.","zh-TW":"把傘帶上。"},{"en":"What brought about this change?","zh-TW":"是什麼引起了這個改變？"}]', '{"verb":"bring"}', NULL, 2, 264),
(265, 'broad', '/brɔːd/', 'adjective', '{"zh-TW":["廣泛的；寬闊的","寬闊的；廣泛的"],"en":["having a large distance from side to side","covering a wide range","wide; covering a large area"]}', '{"root":{"text":"broad","meaning":"wide (寬)"},"logic":"寬的，即「廣泛的」。"}', 'broad range / broad experience / broad spectrum; broad range / broad daylight', '[{"en":"The company offers a broad range of services.","zh-TW":"公司提供廣泛的服務。"},{"en":"She has broad experience in international trade.","zh-TW":"她在國際貿易方面有廣泛經驗。"},{"en":"The river is very broad here.","zh-TW":"河在這裡非常寬。"},{"en":"It happened in broad daylight.","zh-TW":"這發生在光天化日之下。"}]', '{"adverb":"broadly","verb":"broaden"}', NULL, 2, 265),
(266, 'broadcast', '/ˈbrɔːdkæst/', 'verb', '{"zh-TW":["廣播；播放"],"en":["to send out programs by radio or TV"]}', NULL, 'live broadcast / broadcast news', '[{"en":"The game will be broadcast live.","zh-TW":"比賽將現場直播。"},{"en":"The news is broadcast at six.","zh-TW":"新聞在六點播出。"}]', '{"noun":"broadcast","noun2":"broadcaster"}', NULL, 3, 266),
(267, 'broken', '/ˈbroʊkən/', 'adjective', '{"zh-TW":["破碎的；壞掉的"],"en":["damaged and no longer working"]}', NULL, 'broken heart / broken promise', '[{"en":"The window is broken.","zh-TW":"窗戶破了。"},{"en":"He has a broken heart.","zh-TW":"他傷心透了。"}]', NULL, NULL, 2, 267),
(268, 'brother', '/ˈbrʌðər/', 'noun', '{"zh-TW":["兄弟"],"en":["a male sibling"]}', NULL, 'big brother / brother-in-law', '[{"en":"My brother is older than me.","zh-TW":"我哥哥比我大。"},{"en":"They treat each other like brothers.","zh-TW":"他們像兄弟一樣對待彼此。"}]', '{"noun2":"brotherhood"}', NULL, 3, 268),
(269, 'brown', '/braʊn/', 'adjective', '{"zh-TW":["棕色的"],"en":["the color of wood or earth"]}', NULL, 'brown sugar / brown bag', '[{"en":"She has brown eyes.","zh-TW":"她有棕色的眼睛。"},{"en":"The leaves turn brown in autumn.","zh-TW":"秋天葉子變成棕色。"}]', NULL, NULL, 2, 269),
(270, 'browse', '/braʊz/', 'verb', '{"zh-TW":["瀏覽；隨意看看"],"en":["to look at things casually without intent to buy"]}', '{"root":{"text":"browse","meaning":"young shoots (嫩芽)"},"logic":"原指動物啃食嫩芽，後引申為隨意翻閱。"}', 'browse through / browse the internet', '[{"en":"I spent an hour browsing in the bookstore.","zh-TW":"我在書店裡瀏覽了一個小時。"},{"en":"She likes to browse online shops during lunch.","zh-TW":"她喜歡午餐時瀏覽網路商店。"}]', '{"noun":"browser"}', NULL, 2, 270),
(271, 'browser', '/ˈbraʊzər/', 'noun', '{"zh-TW":["瀏覽器"],"en":["a program for accessing websites"]}', NULL, 'web browser / browser history', '[{"en":"Which web browser do you use?","zh-TW":"你使用哪個網頁瀏覽器？"},{"en":"Clear your browser history.","zh-TW":"清除你的瀏覽記錄。"}]', '{"verb":"browse"}', NULL, 3, 271),
(272, 'brush', '/brʌʃ/', 'noun', '{"zh-TW":["刷子；刷"],"en":["a tool with bristles for cleaning or painting"]}', NULL, 'tooth brush / brush up on', '[{"en":"Brush your teeth twice a day.","zh-TW":"每天刷牙兩次。"},{"en":"I need to brush up on my French.","zh-TW":"我需要複習一下法語。"}]', '{"verb":"brush"}', NULL, 2, 272),
(273, 'budget', '/ˈbʌdʒɪt/', 'noun', '{"zh-TW":["預算"],"en":["an estimate of income and expenditure for a set period"]}', '{"root":{"text":"bougette","meaning":"small bag (小袋子)"},"logic":"裝錢的小袋子（分配金額），即「預算」。"}', 'within budget / over budget / annual budget', '[{"en":"The project was completed within budget.","zh-TW":"專案在預算內完成。"},{"en":"We need to cut the budget by 10%.","zh-TW":"我們需要削減10%的預算。"}]', '{"adjective":"budgetary"}', NULL, 2, 273),
(274, 'build', '/bɪld/', 'verb', '{"zh-TW":["建造；建立"],"en":["to construct","to develop over time","to make something by putting parts together"]}', NULL, 'build up / build a team; build up / build on', '[{"en":"We need to build a strong team.","zh-TW":"我們需要建立一支強大的團隊。"},{"en":"They are building a new factory.","zh-TW":"他們正在建造一座新工廠。"},{"en":"They''re building a new house.","zh-TW":"他們正在建一棟新房子。"},{"en":"We need to build trust.","zh-TW":"我們需要建立信任。"}]', '{"verb":"build","noun":"building","noun2":"builder"}', NULL, 2, 274),
(275, 'bulk', '/bʌlk/', 'noun', '{"zh-TW":["大量；大批","體積"],"en":["a large quantity or mass","a large quantity","the mass or size of something"]}', '{"root":{"text":"bulk","meaning":"heap (堆)"},"logic":"大堆的量，即「大量」。"}', 'in bulk / bulk order / bulk purchase', '[{"en":"Ordering in bulk reduces the unit cost.","zh-TW":"大量訂購可降低單位成本。"},{"en":"The bulk of our revenue comes from overseas.","zh-TW":"我們大部分營收來自海外。"},{"en":"Buying in bulk saves money.","zh-TW":"大量採購可以省錢。"},{"en":"The bulk of the work has been completed.","zh-TW":"大部分的工作已經完成。"}]', '{"adjective":"bulky"}', NULL, 1, 275),
(276, 'burden', '/ˈbɜːrdn/', 'noun', '{"zh-TW":["負擔；重擔"],"en":["a heavy load; a duty or responsibility that causes worry","a heavy load; a duty that causes worry"]}', '{"root":{"text":"burden","meaning":"carry (攜帶)"},"logic":"需要攜帶的重量，即「負擔」。"}', 'financial burden / burden on / ease the burden; heavy burden / financial burden / burden of proof', '[{"en":"The new regulations place a heavy burden on small businesses.","zh-TW":"新法規對小企業造成沉重負擔。"},{"en":"Tax cuts helped ease the financial burden on families.","zh-TW":"減稅幫助減輕了家庭的經濟負擔。"},{"en":"The tax increase places a burden on families.","zh-TW":"增稅對家庭造成負擔。"},{"en":"She didn''t want to be a burden to her children.","zh-TW":"她不想成為孩子的負擔。"}]', '{"adjective":"burdensome","verb":"burden"}', NULL, 2, 276),
(277, 'bureau', '/ˈbjʊərəʊ/', 'noun', '{"zh-TW":["局；署；辦公室"],"en":["a government department or agency","an office for business"]}', '{"root":{"text":"bureau","meaning":"desk/office (桌子/辦公室)"},"logic":"辦公的地方，即「局、署」。"}', 'travel bureau / bureau of statistics', '[{"en":"The Bureau of Labor Statistics released new employment data.","zh-TW":"勞動統計局發布了新的就業數據。"},{"en":"Contact the information bureau for details.","zh-TW":"詳情請聯繫資訊服務處。"}]', '{"noun":"bureaucracy","adjective":"bureaucratic"}', NULL, 2, 277),
(278, 'bureaucracy', '/bjʊˈrɒkrəsi/', 'noun', '{"zh-TW":["官僚體制；繁文縟節"],"en":["a system of government with many complicated rules"]}', '{"root":{"text":"bureau","meaning":"office (辦公室)"},"suffix":{"text":"-cracy","meaning":"rule (統治)"},"logic":"辦公室統治，即「官僚體制」。"}', 'government bureaucracy / red tape and bureaucracy', '[{"en":"Excessive bureaucracy slows down the approval process.","zh-TW":"過度的官僚體制拖慢了審批流程。"},{"en":"The company reduced internal bureaucracy to improve efficiency.","zh-TW":"公司減少了內部繁文縟節以提高效率。"}]', '{"adjective":"bureaucratic"}', NULL, 4, 278),
(279, 'burn', '/bɜːrn/', 'verb', '{"zh-TW":["燃燒；燒傷"],"en":["to be on fire; to damage with heat"]}', NULL, 'burn down / burn out', '[{"en":"The candle burned all night.","zh-TW":"蠟燭燃燒了整夜。"},{"en":"She burned her hand on the stove.","zh-TW":"她的手被爐子燙傷了。"}]', NULL, NULL, 1, 279),
(280, 'burst', '/bɜːrst/', 'verb', '{"zh-TW":["爆裂；突然發生"],"en":["to break open suddenly"]}', NULL, 'burst into tears / burst out laughing', '[{"en":"The balloon burst.","zh-TW":"氣球爆了。"},{"en":"She burst into tears.","zh-TW":"她突然哭了起來。"}]', NULL, NULL, 2, 280),
(281, 'bus', '/bʌs/', 'noun', '{"zh-TW":["公車"],"en":["a large vehicle carrying passengers"]}', NULL, 'bus stop / miss the bus', '[{"en":"I take the bus to work.","zh-TW":"我搭公車上班。"},{"en":"We missed the last bus.","zh-TW":"我們錯過了末班車。"}]', NULL, NULL, 1, 281),
(282, 'busy', '/ˈbɪzi/', 'adjective', '{"zh-TW":["忙碌的"],"en":["having a lot to do"]}', NULL, 'busy schedule / busy season; busy with / busy schedule', '[{"en":"She has a very busy schedule this week.","zh-TW":"她這週行程非常忙碌。"},{"en":"December is our busiest season.","zh-TW":"十二月是我們最忙碌的季節。"},{"en":"I''m too busy to talk now.","zh-TW":"我現在太忙了，沒時間說話。"},{"en":"The restaurant is always busy.","zh-TW":"這家餐廳總是很忙。"}]', '{"adjective":"busy","adverb":"busily","noun":"business"}', NULL, 1, 282),
(283, 'butter', '/ˈbʌtər/', 'noun', '{"zh-TW":["奶油"],"en":["a yellow food made from cream"]}', NULL, 'bread and butter / peanut butter', '[{"en":"Spread some butter on the toast.","zh-TW":"在吐司上抹些奶油。"},{"en":"I love peanut butter.","zh-TW":"我喜歡花生醬。"}]', NULL, NULL, 2, 283),
(284, 'button', '/ˈbʌtən/', 'noun', '{"zh-TW":["按鈕；鈕扣"],"en":["a small round object for fastening clothes"]}', NULL, 'push the button / belly button', '[{"en":"Press the button to start.","zh-TW":"按下按鈕開始。"},{"en":"A button fell off my shirt.","zh-TW":"我襯衫上掉了一顆鈕扣。"}]', NULL, NULL, 2, 284),
(285, 'buy', '/baɪ/', 'verb', '{"zh-TW":["購買","買"],"en":["to obtain something by paying money","to get something by paying money"]}', NULL, 'buy in bulk / buy online; buy into / best buy', '[{"en":"We buy office supplies in bulk.","zh-TW":"我們大量採購辦公用品。"},{"en":"More people buy products online now.","zh-TW":"現在更多人在網路上購物。"},{"en":"I want to buy a new phone.","zh-TW":"我想買一支新手機。"},{"en":"She bought groceries after work.","zh-TW":"她下班後買了雜貨。"}]', '{"verb":"buy","noun":"buyer","noun2":"purchase"}', NULL, 1, 285),
(286, 'byproduct', '/ˈbaɪprɒdʌkt/', 'noun', '{"zh-TW":["副產品"],"en":["something produced in addition to the main product"]}', NULL, 'industrial byproduct / unexpected byproduct', '[{"en":"Innovation was a byproduct of the research.","zh-TW":"創新是研究的副產品。"},{"en":"We recycle industrial byproducts.","zh-TW":"我們回收工業副產品。"}]', '{"noun":"byproduct"}', NULL, 3, 286),
(287, 'cabinet', '/ˈkæbɪnɪt/', 'noun', '{"zh-TW":["內閣；櫥櫃","櫥櫃；內閣"],"en":["the group of senior government ministers","a piece of furniture with shelves","a group of senior government ministers"]}', '{"root":{"text":"cabin","meaning":"small room (小房間)"},"suffix":{"text":"-et","meaning":"small (小)"},"logic":"小房間狀的儲物家具，或指內閣。"}', 'cabinet meeting / cabinet minister; kitchen cabinet / cabinet meeting / filing cabinet', '[{"en":"The cabinet met to discuss the crisis.","zh-TW":"內閣開會討論危機。"},{"en":"She was appointed to the cabinet.","zh-TW":"她被任命進入內閣。"},{"en":"The dishes are in the cabinet above the sink.","zh-TW":"碗盤在水槽上方的櫥櫃裡。"},{"en":"The cabinet approved the new policy.","zh-TW":"內閣批准了新政策。"}]', NULL, NULL, 3, 287),
(288, 'cache', '/kæʃ/', 'noun', '{"zh-TW":["快取"],"en":["stored data for quick access"]}', NULL, 'clear cache / cache memory', '[{"en":"Clear the cache to fix the issue.","zh-TW":"清除快取來解決問題。"},{"en":"The browser stores data in the cache.","zh-TW":"瀏覽器將資料存在快取中。"}]', NULL, NULL, 2, 288),
(289, 'cage', '/keɪdʒ/', 'noun', '{"zh-TW":["籠子"],"en":["a structure of bars for keeping animals"]}', NULL, 'bird cage / cage match', '[{"en":"The bird escaped from its cage.","zh-TW":"鳥從籠子裡逃了出來。"},{"en":"The lion paced in its cage.","zh-TW":"獅子在籠子裡踱步。"}]', '{"verb":"cage","adjective":"caged"}', NULL, 1, 289),
(290, 'cake', '/keɪk/', 'noun', '{"zh-TW":["蛋糕"],"en":["a sweet baked food"]}', NULL, 'piece of cake / birthday cake', '[{"en":"Would you like some cake?","zh-TW":"你想要一些蛋糕嗎？"},{"en":"That test was a piece of cake.","zh-TW":"那個考試太容易了。"}]', NULL, NULL, 1, 290),
(291, 'calculate', '/ˈkælkjʊleɪt/', 'verb', '{"zh-TW":["計算；估算","計算"],"en":["to determine by mathematical process","to determine by mathematical methods"]}', '{"root":{"text":"calcul","meaning":"pebble/count (石子/計數)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"用石子計數，即「計算」。"}', 'calculate costs/risk/profit; calculate the cost / carefully calculated', '[{"en":"We need to calculate the total project cost.","zh-TW":"我們需要計算專案總成本。"},{"en":"The software calculates tax automatically.","zh-TW":"軟體會自動計算稅金。"},{"en":"Can you calculate the total cost?","zh-TW":"你能計算總費用嗎？"},{"en":"The risk was carefully calculated.","zh-TW":"風險經過仔細計算。"}]', '{"noun":"calculation","noun2":"calculator"}', NULL, 3, 291),
(292, 'call', '/kɔːl/', 'verb', '{"zh-TW":["打電話；稱呼"],"en":["to telephone","to give a name to"]}', NULL, 'call back / conference call', '[{"en":"I will call you back in five minutes.","zh-TW":"我五分鐘後回電給你。"},{"en":"We have a conference call at 3 p.m.","zh-TW":"我們下午3點有一通電話會議。"}]', '{"verb":"call","noun":"call","noun2":"caller"}', NULL, 1, 292),
(293, 'calm', '/kɑːm/', 'adjective', '{"zh-TW":["平靜的；冷靜的"],"en":["not excited or upset; peaceful","not showing or feeling nervousness or anger"]}', '{"root":{"text":"calm","meaning":"still/quiet (靜止)"},"logic":"源自希臘語 kauma（炎熱中的休息），指平靜狀態。"}', 'stay calm / calm down; stay calm / calm down / calm and collected', '[{"en":"Please stay calm during the evacuation.","zh-TW":"疏散時請保持冷靜。"},{"en":"The manager remained calm under pressure.","zh-TW":"經理在壓力下保持冷靜。"},{"en":"Please stay calm during the emergency.","zh-TW":"緊急情況時請保持冷靜。"},{"en":"The sea was perfectly calm that morning.","zh-TW":"那天早上海面非常平靜。"}]', '{"adjective":"calm","verb":"calm","noun":"calmness","adverb":"calmly"}', NULL, 1, 293),
(294, 'camera', '/ˈkæmərə/', 'noun', '{"zh-TW":["相機"],"en":["a device for taking photographs"]}', NULL, 'security camera / camera angle', '[{"en":"I forgot my camera at home.","zh-TW":"我把相機忘在家裡了。"},{"en":"The store has security cameras.","zh-TW":"商店裝有監視器。"}]', NULL, NULL, 2, 294),
(295, 'camp', '/kæmp/', 'noun', '{"zh-TW":["營地；露營"],"en":["a place with tents for staying outdoors"]}', NULL, 'summer camp / camp out', '[{"en":"The kids went to summer camp.","zh-TW":"孩子們去了夏令營。"},{"en":"We camped by the lake.","zh-TW":"我們在湖邊露營。"}]', '{"verb":"camp","noun2":"camping","noun3":"campsite"}', NULL, 1, 295),
(296, 'campaign', '/kæmˈpeɪn/', 'noun', '{"zh-TW":["活動；運動","宣傳","競選活動；運動","活動；競選"],"en":["an organized course of action to achieve a goal","organized activities to achieve a goal"]}', '{"root":{"text":"camp","meaning":"field (原野)"},"suffix":{"text":"-aign","meaning":"action (行動)"},"logic":"在原野上的行動，即「活動」。"}', 'marketing campaign / advertising campaign / launch a campaign; election campaign / advertising campaign; advertising campaign / election campaign / launch a campaign', '[{"en":"The marketing campaign generated significant leads.","zh-TW":"行銷活動產生了大量潛在客戶。"},{"en":"They launched a campaign to promote sustainability.","zh-TW":"他們發起了促進永續發展的活動。"},{"en":"The campaign starts next month.","zh-TW":"競選活動下個月開始。"},{"en":"They launched a campaign against smoking.","zh-TW":"他們發起了反菸運動。"},{"en":"The company launched a new marketing campaign.","zh-TW":"公司發起了新的行銷活動。"},{"en":"She is running a campaign for mayor.","zh-TW":"她正在競選市長。"}]', '{"verb":"campaign","noun2":"campaigner"}', NULL, 3, 296),
(297, 'campus', '/ˈkæmpəs/', 'noun', '{"zh-TW":["校園"],"en":["the grounds of a university or college"]}', NULL, 'on campus / campus life', '[{"en":"The university has a beautiful campus.","zh-TW":"這所大學有一個美麗的校園。"},{"en":"Students live on campus.","zh-TW":"學生住在校園裡。"}]', NULL, NULL, 2, 297),
(298, 'candidate', '/ˈkændɪdət/', 'noun', '{"zh-TW":["候選人；應徵者"],"en":["a person who applies for a job or is nominated for a position"]}', '{"root":{"text":"candid","meaning":"white (白色)"},"suffix":{"text":"-ate","meaning":"person (人)"},"logic":"穿白袍的人（古羅馬參選者），即「候選人」。"}', 'ideal candidate / qualified candidate / shortlist candidates', '[{"en":"We interviewed five candidates for the position.","zh-TW":"我們面試了五位候選人。"},{"en":"The ideal candidate should have 5+ years of experience.","zh-TW":"理想候選人應有5年以上經驗。"}]', '{"noun":"candidacy"}', NULL, 3, 298),
(299, 'canvas', '/ˈkænvəs/', 'noun', '{"zh-TW":["畫布"],"en":["a strong cloth used for painting on"]}', '{"root":{"text":"canvas","meaning":"hemp cloth (麻布)"},"logic":"源自拉丁語 cannabis（大麻），原指麻布。"}', 'oil on canvas / blank canvas', '[{"en":"The artist stretched a new canvas.","zh-TW":"藝術家繃上一塊新畫布。"},{"en":"The painting is oil on canvas.","zh-TW":"這幅畫是油畫。"}]', NULL, NULL, 2, 299);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(300, 'cap', '/kæp/', 'noun', '{"zh-TW":["帽子；蓋子"],"en":["a type of soft hat; a covering for a bottle"]}', NULL, 'baseball cap / cap off', '[{"en":"He always wears a baseball cap.","zh-TW":"他總是戴著棒球帽。"},{"en":"Put the cap back on the bottle.","zh-TW":"把瓶蓋蓋回去。"}]', NULL, NULL, 1, 300),
(301, 'capable', '/ˈkeɪpəbl/', 'adjective', '{"zh-TW":["有能力的"],"en":["having the ability or quality to do something","having the ability to do something"]}', '{"root":{"text":"cap","meaning":"take/hold (拿/容納)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠容納的，即「有能力的」。"}', 'capable of / highly capable', '[{"en":"She is capable of managing large-scale projects.","zh-TW":"她有能力管理大型專案。"},{"en":"We need a capable leader for this division.","zh-TW":"我們需要一位有能力的人來領導這個部門。"},{"en":"She is capable of handling the task alone.","zh-TW":"她有能力獨自處理這項任務。"},{"en":"He is a highly capable manager.","zh-TW":"他是一位非常能幹的經理。"}]', '{"noun":"capability"}', NULL, 3, 301),
(302, 'capacity', '/kəˈpæsəti/', 'noun', '{"zh-TW":["容量；能力","身份"],"en":["the maximum amount that can be contained","the ability or power to do something"]}', '{"root":{"text":"cap","meaning":"hold (容納)"},"suffix":{"text":"-acity","meaning":"state of (狀態)"},"logic":"能容納的狀態，即「容量」。"}', 'full capacity / production capacity / in the capacity of', '[{"en":"The factory is operating at full capacity.","zh-TW":"工廠正以滿產能運作。"},{"en":"He served in the capacity of financial advisor.","zh-TW":"他以財務顧問的身份服務。"}]', NULL, NULL, 3, 302),
(303, 'capital', '/ˈkæpɪtl/', 'noun', '{"zh-TW":["資本；首都"],"en":["wealth owned by a person or organization","the city serving as seat of government"]}', '{"root":{"text":"capit","meaning":"head (頭)"},"suffix":{"text":"-al","meaning":"relating to (有關的)"},"logic":"頭部（最重要的），即「首都、資本」。"}', 'raise capital / venture capital / capital investment', '[{"en":"The startup raised $10 million in venture capital.","zh-TW":"這家新創公司籌集了1000萬美元的風險投資。"},{"en":"Significant capital investment is needed for expansion.","zh-TW":"擴張需要大量的資本投資。"}]', '{"verb":"capitalize","noun":"capitalism"}', NULL, 3, 303),
(304, 'capitalize', '/ˈkæpɪtəlaɪz/', 'verb', '{"zh-TW":["利用；資本化"],"en":["to take advantage of an opportunity","to provide with capital"]}', '{"root":{"text":"capital","meaning":"capital (資本)"},"suffix":{"text":"-ize","meaning":"to make (使)"},"logic":"使成為資本（利用資源），即「利用」。"}', 'capitalize on opportunity / capitalize assets', '[{"en":"We must capitalize on this market opportunity.","zh-TW":"我們必須利用這個市場機會。"},{"en":"The startup needs to capitalize its operations.","zh-TW":"這家新創公司需要為營運提供資金。"}]', '{"noun":"capitalization"}', NULL, 4, 304),
(305, 'captain', '/ˈkæptɪn/', 'noun', '{"zh-TW":["隊長；船長"],"en":["the leader of a team or ship"]}', NULL, 'team captain / captain of industry', '[{"en":"She is the team captain.","zh-TW":"她是隊長。"},{"en":"The captain steered the ship safely.","zh-TW":"船長安全地駕駛了船。"}]', NULL, NULL, 3, 305),
(306, 'capture', '/ˈkæptʃər/', 'verb', '{"zh-TW":["捕獲；佔領","吸引","捕獲；捕捉"],"en":["to take control or possession of","to attract and hold attention","to catch a person or animal"]}', '{"root":{"text":"capt","meaning":"take/seize (抓取)"},"suffix":{"text":"-ure","meaning":"action (動作)"},"logic":"抓取的動作，即「捕獲」。"}', 'capture market share / capture attention / capture data; capture attention / capture the moment', '[{"en":"The company captured 30% of the market share.","zh-TW":"公司佔據了30%的市場份額。"},{"en":"The presentation captured everyone''s attention.","zh-TW":"簡報吸引了所有人的注意力。"},{"en":"The photo captured the moment perfectly.","zh-TW":"這張照片完美地捕捉了那一刻。"},{"en":"The criminal was captured by police.","zh-TW":"罪犯被警察逮捕了。"}]', '{"noun":"capture"}', NULL, 3, 306),
(307, 'car', '/kɑːr/', 'noun', '{"zh-TW":["汽車"],"en":["a motor vehicle for passengers","a road vehicle with an engine"]}', NULL, 'by car / car park', '[{"en":"She drives to work by car.","zh-TW":"她開車上班。"},{"en":"The car park is behind the building.","zh-TW":"停車場在大樓後面。"},{"en":"I need to fix my car.","zh-TW":"我需要修理我的車。"}]', '{"noun":"car"}', NULL, 1, 307),
(308, 'carbon', '/ˈkɑːrbən/', 'noun', '{"zh-TW":["碳"],"en":["a chemical element found in all living things"]}', '{"root":{"text":"carbon","meaning":"coal (�ite)"},"logic":"源自拉丁語 carbo（煤炭）。"}', 'carbon dioxide / carbon footprint / carbon emissions', '[{"en":"Trees absorb carbon dioxide from the atmosphere.","zh-TW":"樹木從大氣中吸收二氧化碳。"},{"en":"We should reduce our carbon footprint.","zh-TW":"我們應該減少碳足跡。"}]', NULL, NULL, 2, 308),
(309, 'card', '/kɑːrd/', 'noun', '{"zh-TW":["卡片；紙牌"],"en":["a piece of stiff paper; a credit card"]}', NULL, 'credit card / playing cards', '[{"en":"Can I pay by card?","zh-TW":"我可以刷卡嗎？"},{"en":"She sent me a birthday card.","zh-TW":"她寄了一張生日卡給我。"}]', NULL, NULL, 1, 309),
(310, 'career', '/kəˈrɪər/', 'noun', '{"zh-TW":["職業；職涯"],"en":["an occupation undertaken for a significant period of one''s life"]}', '{"root":{"text":"carr","meaning":"road/vehicle (路/車)"},"suffix":{"text":"-eer","meaning":"person engaged in (從事…的人)"},"logic":"人生道路上從事的，即「職業」。"}', 'career development / career path / career change', '[{"en":"She made a career change from finance to tech.","zh-TW":"她從金融轉職到科技業。"},{"en":"The company offers excellent career development opportunities.","zh-TW":"公司提供優秀的職涯發展機會。"}]', NULL, NULL, 2, 310),
(311, 'careful', '/ˈkɛərfəl/', 'adjective', '{"zh-TW":["小心的；仔細的"],"en":["giving attention to avoid mistakes or danger","giving attention to avoid danger or mistakes"]}', NULL, 'be careful / careful planning; be careful / careful with', '[{"en":"Be careful with the fragile items.","zh-TW":"小心處理易碎物品。"},{"en":"Careful planning led to success.","zh-TW":"仔細的規劃帶來了成功。"},{"en":"Be careful crossing the road.","zh-TW":"過馬路要小心。"},{"en":"She''s very careful with money.","zh-TW":"她花錢很謹慎。"}]', '{"adjective":"careful","adverb":"carefully","noun":"care","adjective2":"careless"}', NULL, 3, 311),
(312, 'cargo', '/ˈkɑːrɡəʊ/', 'noun', '{"zh-TW":["貨物"],"en":["goods carried by a vehicle, ship, or aircraft"]}', '{"root":{"text":"carg","meaning":"load (裝載)"},"suffix":{"text":"-o","meaning":"noun ending (名詞字尾)"},"logic":"裝載的東西，即「貨物」。"}', 'cargo ship / air cargo / cargo container', '[{"en":"The cargo was damaged during transit.","zh-TW":"貨物在運輸過程中受損。"},{"en":"Air cargo rates have increased significantly.","zh-TW":"空運費率大幅上漲。"}]', NULL, NULL, 2, 312),
(313, 'carry', '/ˈkæri/', 'verb', '{"zh-TW":["攜帶；執行","承擔"],"en":["to transport or convey","to support the weight of"]}', '{"root":{"text":"carry","meaning":"transport (運送)"},"logic":"運送，即「攜帶」。"}', 'carry out / carry on / carry risk', '[{"en":"The team will carry out the plan next quarter.","zh-TW":"團隊將在下季度執行計畫。"},{"en":"All investments carry some degree of risk.","zh-TW":"所有投資都帶有一定程度的風險。"}]', '{"noun":"carrier"}', NULL, 2, 313),
(314, 'cart', '/kɑːrt/', 'noun', '{"zh-TW":["購物車；手推車"],"en":["a vehicle with wheels used for carrying goods"]}', '{"root":{"text":"cart","meaning":"vehicle (車)"},"logic":"源自古英語 cræt（車），指用於搬運的推車。"}', 'shopping cart / add to cart', '[{"en":"Please put the items in the cart.","zh-TW":"請把商品放進購物車。"},{"en":"She added three items to her online cart.","zh-TW":"她在網路購物車中加了三樣商品。"}]', '{"verb":"cart"}', NULL, 1, 314),
(315, 'carve', '/kɑːrv/', 'verb', '{"zh-TW":["雕刻"],"en":["to cut a hard material to produce a shape"]}', '{"root":{"text":"carve","meaning":"cut (切割)"},"logic":"源自古英語 ceorfan（切割）。"}', 'carve a statue / carve wood / carve out', '[{"en":"He carved a beautiful figure from wood.","zh-TW":"他用木頭雕刻了一個美麗的人像。"},{"en":"The sculptor carved the marble with great skill.","zh-TW":"雕塑家以高超技藝雕刻大理石。"}]', '{"noun":"carving","noun2":"carver"}', NULL, 2, 315),
(316, 'cashier', '/kæˈʃɪr/', 'noun', '{"zh-TW":["收銀員"],"en":["a person who handles payments in a store"]}', '{"root":{"text":"cash","meaning":"money (現金)"},"suffix":{"text":"-ier","meaning":"person who (從事…的人)"},"logic":"處理現金的人，即「收銀員」。"}', 'cashier counter / head cashier', '[{"en":"The cashier scanned all the items.","zh-TW":"收銀員掃描了所有商品。"},{"en":"Please pay the cashier at the front.","zh-TW":"請到前面的收銀台付款。"}]', '{"noun":"cash"}', NULL, 3, 316),
(317, 'casual', '/ˈkæʒuəl/', 'adjective', '{"zh-TW":["休閒的；隨意的"],"en":["relaxed and unconcerned","not formal"]}', '{"root":{"text":"cas","meaning":"fall/chance (偶然)"},"suffix":{"text":"-ual","meaning":"relating to (相關的)"},"logic":"與偶然相關的，指不正式的、隨意的。"}', 'casual clothes / casual conversation / casual worker', '[{"en":"The dress code is casual on Fridays.","zh-TW":"週五的穿著規定是休閒服。"},{"en":"It was just a casual remark.","zh-TW":"那只是一句隨口說說。"}]', '{"adverb":"casually"}', NULL, 2, 317),
(318, 'catalog', '/ˈkætəlɒɡ/', 'noun', '{"zh-TW":["目錄；型錄"],"en":["a complete list of items arranged systematically"]}', '{"prefix":{"text":"cata-","meaning":"down/complete (完全)"},"root":{"text":"log","meaning":"word/list (字/列表)"},"logic":"完全列出的清單，即「目錄」。"}', 'product catalog / catalog of services', '[{"en":"Please refer to our online product catalog.","zh-TW":"請參閱我們的線上產品目錄。"},{"en":"The catalog lists over 5,000 items.","zh-TW":"目錄列出了5,000多項商品。"}]', NULL, NULL, 3, 318),
(319, 'catch', '/kætʃ/', 'verb', '{"zh-TW":["接住；趕上；染上"],"en":["to get hold of something moving"]}', NULL, 'catch up / catch a cold', '[{"en":"Catch the ball!","zh-TW":"接住球！"},{"en":"I caught a cold last week.","zh-TW":"我上週感冒了。"}]', NULL, NULL, 2, 319),
(320, 'category', '/ˈkætəɡəri/', 'noun', '{"zh-TW":["類別；種類"],"en":["a class or division of people or things"]}', '{"prefix":{"text":"cata-","meaning":"down (完全)"},"root":{"text":"gor","meaning":"speak/accuse (說/指出)"},"suffix":{"text":"-y","meaning":"noun ending (名詞字尾)"},"logic":"指出分類，即「類別」。"}', 'product category / fall into a category', '[{"en":"The products are divided into five main categories.","zh-TW":"產品分為五大類。"},{"en":"This expense falls into the travel category.","zh-TW":"此費用屬於差旅類別。"}]', '{"verb":"categorize","adjective":"categorical"}', NULL, 3, 320),
(321, 'cater', '/ˈkeɪtər/', 'verb', '{"zh-TW":["迎合；提供餐飲服務"],"en":["to provide what is needed or required","to supply food and drink"]}', '{"root":{"text":"cater","meaning":"provide food (提供食物)"},"logic":"提供所需，即「迎合」。"}', 'cater to / cater for / catering service', '[{"en":"Our services cater to small and medium businesses.","zh-TW":"我們的服務迎合中小企業。"},{"en":"The hotel caters for corporate events.","zh-TW":"飯店承辦企業活動。"}]', '{"noun":"catering"}', NULL, 2, 321),
(322, 'cause', '/kɔːz/', 'noun', '{"zh-TW":["原因；引起"],"en":["the reason something happens","to make something happen"]}', NULL, 'root cause / cause damage', '[{"en":"We need to find the root cause.","zh-TW":"我們需要找出根本原因。"},{"en":"The storm caused major delays.","zh-TW":"暴風雨造成了嚴重的延誤。"}]', '{"noun":"cause","verb":"cause"}', NULL, 2, 322),
(323, 'cautious', '/ˈkɔːʃəs/', 'adjective', '{"zh-TW":["謹慎的；小心的"],"en":["careful to avoid potential problems or dangers"]}', '{"root":{"text":"caut","meaning":"be on guard (警戒)"},"suffix":{"text":"-ious","meaning":"full of (充滿)"},"logic":"充滿警戒的，即「謹慎的」。"}', 'cautious approach / cautious driver', '[{"en":"She is cautious about investing her money.","zh-TW":"她對投資很謹慎。"},{"en":"A cautious approach is recommended.","zh-TW":"建議採取謹慎的做法。"}]', '{"noun":"caution","adverb":"cautiously"}', NULL, 3, 323),
(324, 'cease', '/siːs/', 'verb', '{"zh-TW":["停止；終止","停止"],"en":["to come or bring to an end","to come to an end; to stop"]}', '{"root":{"text":"cess","meaning":"go/yield (走/讓步)"},"logic":"讓步停下來，即「停止」。"}', 'cease operations / cease to exist; cease operations / cease to exist / cease-fire', '[{"en":"The factory will cease operations at the end of the month.","zh-TW":"工廠將在月底停止營運。"},{"en":"The company has ceased trading.","zh-TW":"公司已停止營業。"},{"en":"The factory will cease operations next month.","zh-TW":"工廠下個月將停止運營。"},{"en":"The company ceased to exist after bankruptcy.","zh-TW":"公司破產後就不復存在了。"}]', '{"noun":"cessation","adjective":"ceaseless"}', NULL, 2, 324),
(325, 'celebrate', '/ˈselɪbreɪt/', 'verb', '{"zh-TW":["慶祝"],"en":["to mark an event with festivities"]}', '{"root":{"text":"celebr","meaning":"honor (尊崇)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使其受到尊崇紀念，即「慶祝」。"}', 'celebrate a birthday / celebrate success', '[{"en":"They celebrated their anniversary with a dinner.","zh-TW":"他們以晚餐慶祝結婚紀念日。"},{"en":"The team celebrated their victory.","zh-TW":"團隊慶祝了他們的勝利。"}]', '{"noun":"celebration"}', NULL, 3, 325),
(326, 'celebrity', '/sɪˈlɛbrɪti/', 'noun', '{"zh-TW":["名人"],"en":["a famous person"]}', NULL, 'celebrity status / celebrity gossip', '[{"en":"Many celebrities attended the event.","zh-TW":"許多名人出席了活動。"},{"en":"She became a celebrity overnight.","zh-TW":"她一夜成名。"}]', NULL, NULL, 3, 326),
(327, 'cell', '/sɛl/', 'noun', '{"zh-TW":["細胞；牢房；手機"],"en":["the smallest unit of a living thing"]}', NULL, 'cell phone / prison cell', '[{"en":"Red blood cells carry oxygen.","zh-TW":"紅血球攜帶氧氣。"},{"en":"What''s your cell phone number?","zh-TW":"你的手機號碼是什麼？"}]', NULL, NULL, 1, 327),
(328, 'census', '/ˈsɛnsəs/', 'noun', '{"zh-TW":["人口普查"],"en":["an official count of the population"]}', NULL, 'national census / census data', '[{"en":"The census is conducted every ten years.","zh-TW":"人口普查每十年進行一次。"},{"en":"Census data shows population growth.","zh-TW":"人口普查數據顯示人口成長。"}]', NULL, NULL, 2, 328),
(329, 'center', '/ˈsɛntər/', 'noun', '{"zh-TW":["中心；中央"],"en":["the middle point","a building for a particular activity","the middle point of something"]}', NULL, 'shopping center / call center; city center / shopping center', '[{"en":"The call center operates 24 hours.","zh-TW":"客服中心24小時運營。"},{"en":"The city center is very busy.","zh-TW":"市中心非常繁忙。"},{"en":"The hotel is in the city center.","zh-TW":"飯店在市中心。"},{"en":"She is the center of attention.","zh-TW":"她是眾人關注的焦點。"}]', '{"noun":"center","adjective":"central","verb":"centralize","adverb":"centrally"}', NULL, 2, 329),
(330, 'centralize', '/ˈsentrəlaɪz/', 'verb', '{"zh-TW":["集中化"],"en":["to bring under a single central authority"]}', '{"root":{"text":"centr","meaning":"center (中心)"},"suffix":{"text":"-alize","meaning":"to make (使)"},"logic":"使集中到中心，即「集中化」。"}', 'centralize operations/management/control', '[{"en":"The company centralized all IT operations.","zh-TW":"公司將所有IT營運集中化。"},{"en":"Centralizing procurement can reduce costs.","zh-TW":"集中採購可以降低成本。"}]', '{"noun":"centralization","adjective":"centralized"}', NULL, 4, 330),
(331, 'ceramic', '/səˈræmɪk/', 'noun', '{"zh-TW":["陶瓷"],"en":["objects made from clay that is heated to high temperatures"]}', '{"root":{"text":"ceram","meaning":"potter''s clay (陶土)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"與陶土相關的，即「陶瓷」。"}', 'ceramic tile / ceramic art', '[{"en":"The floor is covered with ceramic tiles.","zh-TW":"地板鋪著瓷磚。"},{"en":"She took a ceramic art class.","zh-TW":"她上了一堂陶藝課。"}]', '{"noun":"ceramics"}', NULL, 3, 331),
(332, 'certain', '/ˈsɜːrtən/', 'adjective', '{"zh-TW":["確定的；某些"],"en":["sure; having no doubt","specific but not named"]}', NULL, 'for certain / certain conditions', '[{"en":"I am certain the data is correct.","zh-TW":"我確定資料是正確的。"},{"en":"Certain conditions must be met.","zh-TW":"必須滿足某些條件。"}]', '{"adjective":"certain","adverb":"certainly","noun":"certainty"}', NULL, 3, 332),
(333, 'certificate', '/sərˈtɪfɪkət/', 'noun', '{"zh-TW":["證書；執照","證書；證明"],"en":["an official document attesting a fact","an official document proving something"]}', '{"root":{"text":"cert","meaning":"sure (確定)"},"suffix":{"text":"-ificate","meaning":"thing made (製成品)"},"logic":"使確定的文件，即「證書」。"}', 'certificate of completion / professional certificate; birth certificate / certificate program', '[{"en":"Applicants must provide a certificate of qualification.","zh-TW":"申請者必須提供資格證書。"},{"en":"She earned a professional certificate in project management.","zh-TW":"她取得了專案管理的專業證書。"},{"en":"She received a certificate of completion.","zh-TW":"她收到了結業證書。"},{"en":"You need a birth certificate to apply.","zh-TW":"你需要出生證明才能申請。"}]', '{"verb":"certify","noun":"certification","noun2":"certification"}', NULL, 4, 333),
(334, 'chain', '/tʃeɪn/', 'noun', '{"zh-TW":["鏈條；連鎖"],"en":["a series of metal rings connected together"]}', NULL, 'food chain / chain reaction', '[{"en":"The dog was on a chain.","zh-TW":"狗被拴在鏈條上。"},{"en":"It''s a popular restaurant chain.","zh-TW":"這是一家受歡迎的連鎖餐廳。"}]', NULL, NULL, 2, 334),
(335, 'chair', '/tʃɛr/', 'noun', '{"zh-TW":["椅子；主席"],"en":["a piece of furniture for sitting"]}', NULL, 'arm chair / chair a meeting', '[{"en":"Please have a seat in this chair.","zh-TW":"請坐在這把椅子上。"},{"en":"She chairs the committee.","zh-TW":"她主持委員會。"}]', '{"noun2":"chairman"}', NULL, 2, 335),
(336, 'challenge', '/ˈtʃælɪndʒ/', 'noun', '{"zh-TW":["挑戰；難題"],"en":["a task or situation that tests abilities"]}', '{"root":{"text":"challenge","meaning":"accusation/call to fight (指控/挑戰)"},"logic":"呼叫對抗，即「挑戰」。"}', 'face a challenge / overcome challenges / major challenge', '[{"en":"The biggest challenge is meeting the tight deadline.","zh-TW":"最大的挑戰是趕上緊迫的截止日期。"},{"en":"We must overcome these challenges to succeed.","zh-TW":"我們必須克服這些挑戰才能成功。"}]', '{"adjective":"challenging"}', NULL, 3, 336),
(337, 'chamber', '/ˈtʃeɪmbər/', 'noun', '{"zh-TW":["會議廳；商會"],"en":["a large room used for meetings","an enclosed space"]}', '{"root":{"text":"camer","meaning":"room (房間)"},"logic":"房間，即「會議廳」。"}', 'chamber of commerce / chamber music', '[{"en":"The chamber of commerce supports local businesses.","zh-TW":"商會支持當地企業。"},{"en":"The proposal was debated in the upper chamber.","zh-TW":"該提案在上議院進行辯論。"}]', NULL, NULL, 3, 337),
(338, 'championship', '/ˈtʃæmpiənʃɪp/', 'noun', '{"zh-TW":["錦標賽；冠軍地位"],"en":["a competition to find the best player or team"]}', NULL, 'world championship / win the championship', '[{"en":"They won the national championship.","zh-TW":"他們贏得了全國錦標賽。"},{"en":"The championship game is tomorrow.","zh-TW":"冠軍賽明天舉行。"}]', '{"noun2":"champion"}', NULL, 4, 338),
(339, 'chance', '/tʃæns/', 'noun', '{"zh-TW":["機會；可能性"],"en":["an opportunity","possibility of something happening","an opportunity; a possibility"]}', NULL, 'by chance / take a chance', '[{"en":"There is a good chance of promotion.","zh-TW":"有很好的升遷機會。"},{"en":"We met by chance at the airport.","zh-TW":"我們在機場巧遇。"},{"en":"Give me one more chance.","zh-TW":"再給我一次機會。"},{"en":"We met by chance at the airport.","zh-TW":"我們在機場偶然相遇。"}]', '{"noun":"chance","adjective":"chance"}', NULL, 2, 339),
(340, 'change', '/tʃeɪndʒ/', 'verb', '{"zh-TW":["改變；變化","改變；更換"],"en":["to make or become different","to become different or make something different"]}', NULL, 'make a change / change of plan; change mind / climate change', '[{"en":"We need to change our strategy.","zh-TW":"我們需要改變策略。"},{"en":"There has been a change of plan.","zh-TW":"計畫有了變動。"},{"en":"People can change.","zh-TW":"人是可以改變的。"},{"en":"I need to change my clothes.","zh-TW":"我需要換衣服。"}]', '{"verb":"change","noun":"change","adjective":"changeable"}', NULL, 2, 340),
(341, 'channel', '/ˈtʃænl/', 'noun', '{"zh-TW":["管道；頻道","途徑"],"en":["a medium for communication or distribution"]}', '{"root":{"text":"canal","meaning":"canal/pipe (運河/管道)"},"logic":"傳送的管道，即「頻道、途徑」。"}', 'distribution channel / sales channel / communication channel', '[{"en":"We use multiple channels to reach our customers.","zh-TW":"我們使用多種管道接觸客戶。"},{"en":"Social media has become an important marketing channel.","zh-TW":"社群媒體已成為重要的行銷管道。"}]', NULL, NULL, 3, 341),
(342, 'chapter', '/ˈtʃæptər/', 'noun', '{"zh-TW":["章節"],"en":["a main division of a book"]}', NULL, 'new chapter / chapter by chapter', '[{"en":"Read chapter three for homework.","zh-TW":"回家作業請讀第三章。"},{"en":"A new chapter of her life began.","zh-TW":"她人生的新篇章開始了。"}]', NULL, NULL, 3, 342),
(343, 'character', '/ˈkærɪktər/', 'noun', '{"zh-TW":["角色；性格；字元"],"en":["a person in a story; the qualities of a person"]}', NULL, 'main character / out of character', '[{"en":"Who is your favorite character?","zh-TW":"你最喜歡的角色是誰？"},{"en":"That behavior is out of character for him.","zh-TW":"那種行為不像他。"}]', '{"noun2":"characteristic"}', NULL, 3, 343),
(344, 'characteristic', '/ˌkærɪktəˈrɪstɪk/', 'noun', '{"zh-TW":["特徵；特性"],"en":["a feature typical of a person or thing"]}', '{"root":{"text":"character","meaning":"mark/stamp (標記)"},"suffix":{"text":"-istic","meaning":"relating to (相關的)"},"logic":"與標記相關的特點，即「特徵」。"}', 'key characteristic / distinctive characteristic', '[{"en":"Patience is one of her best characteristics.","zh-TW":"耐心是她最好的特質之一。"},{"en":"What are the characteristics of this material?","zh-TW":"這種材料的特性是什麼？"}]', '{"verb":"characterize","adverb":"characteristically"}', NULL, 5, 344),
(345, 'charge', '/tʃɑːrdʒ/', 'verb', '{"zh-TW":["收費；控告","負責","收費；充電；控告"],"en":["to ask for a price","to formally accuse of a crime","to ask for money; to fill with electrical energy"]}', '{"root":{"text":"charge","meaning":"load (裝載)"},"logic":"裝載責任或費用，即「收費、負責」。"}', 'free of charge / in charge of / charge a fee; in charge of / free of charge', '[{"en":"There is no charge for delivery orders over $50.","zh-TW":"超過50美元的訂單免收運費。"},{"en":"She is in charge of the marketing department.","zh-TW":"她負責行銷部門。"},{"en":"How much do you charge?","zh-TW":"你收費多少？"},{"en":"Who''s in charge here?","zh-TW":"這裡誰負責？"}]', '{"noun":"charge"}', NULL, 2, 345),
(346, 'chase', '/tʃeɪs/', 'verb', '{"zh-TW":["追趕；追求"],"en":["to run after someone to catch them"]}', NULL, 'chase after / wild goose chase', '[{"en":"The dog chased the cat.","zh-TW":"狗追著貓跑。"},{"en":"Stop chasing your dreams and start building them.","zh-TW":"別再追夢了，開始實現它們吧。"}]', NULL, NULL, 2, 346),
(347, 'cheap', '/tʃiːp/', 'adjective', '{"zh-TW":["便宜的"],"en":["low in price; not expensive","costing little money"]}', NULL, 'cheap price / cheap labor; dirt cheap / cheap shot', '[{"en":"We found a cheaper supplier.","zh-TW":"我們找到了更便宜的供應商。"},{"en":"Cheap labor attracts manufacturers.","zh-TW":"廉價勞工吸引了製造商。"},{"en":"This bag was really cheap.","zh-TW":"這個包很便宜。"},{"en":"Flying is cheaper than taking the train.","zh-TW":"搭飛機比搭火車便宜。"}]', '{"adjective":"cheap","adverb":"cheaply","verb":"cheapen"}', NULL, 2, 347),
(348, 'check', '/tʃɛk/', 'verb', '{"zh-TW":["檢查；核對"],"en":["to examine something to see if it is correct"]}', NULL, 'check in / check out', '[{"en":"Let me check my email.","zh-TW":"讓我查看一下我的電子郵件。"},{"en":"Please check in at the front desk.","zh-TW":"請到前台辦理入住。"}]', NULL, NULL, 2, 348),
(349, 'cheerful', '/ˈtʃɪrfl/', 'adjective', '{"zh-TW":["愉快的；開朗的"],"en":["happy and positive in feeling or attitude"]}', '{"root":{"text":"cheer","meaning":"face/mood (表情/心情)"},"suffix":{"text":"-ful","meaning":"full of (充滿)"},"logic":"充滿好心情的，即「愉快的」。"}', 'cheerful smile / cheerful personality', '[{"en":"She has a cheerful personality.","zh-TW":"她有開朗的個性。"},{"en":"The room was bright and cheerful.","zh-TW":"房間明亮又令人愉悅。"}]', '{"noun":"cheerfulness","adverb":"cheerfully","verb":"cheer"}', NULL, 3, 349);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(350, 'cheese', '/tʃiːz/', 'noun', '{"zh-TW":["起司；乳酪"],"en":["a solid food made from milk"]}', NULL, 'cream cheese / cheese cake', '[{"en":"Would you like some cheese?","zh-TW":"你要一些起司嗎？"},{"en":"Say cheese for the photo!","zh-TW":"拍照時說起司！"}]', NULL, NULL, 2, 350),
(351, 'chest', '/tʃɛst/', 'noun', '{"zh-TW":["胸部；箱子"],"en":["the front part of the body between neck and stomach"]}', NULL, 'chest pain / treasure chest', '[{"en":"He felt a pain in his chest.","zh-TW":"他感到胸口疼痛。"},{"en":"They found a treasure chest.","zh-TW":"他們找到了一個寶箱。"}]', NULL, NULL, 2, 351),
(352, 'chicken', '/ˈtʃɪkɪn/', 'noun', '{"zh-TW":["雞；雞肉"],"en":["a common farm bird; its meat used as food"]}', NULL, 'fried chicken / chicken out', '[{"en":"I''ll have the grilled chicken.","zh-TW":"我要烤雞。"},{"en":"Don''t chicken out now!","zh-TW":"現在別退縮！"}]', NULL, NULL, 3, 352),
(353, 'chief', '/tʃiːf/', 'adjective', '{"zh-TW":["主要的；首要的","首長"],"en":["most important","the leader of a group"]}', '{"root":{"text":"chief","meaning":"head (頭)"},"logic":"頭部的，即「主要的」。"}', 'chief executive / chief concern / chief officer', '[{"en":"The chief executive addressed the shareholders.","zh-TW":"執行長向股東們致辭。"},{"en":"Cost reduction is our chief concern right now.","zh-TW":"降低成本是我們目前的首要關注。"}]', '{"adverb":"chiefly"}', NULL, 2, 353),
(354, 'chip', '/tʃɪp/', 'noun', '{"zh-TW":["晶片；薯片"],"en":["a tiny piece of silicon with electronic circuits"]}', NULL, 'computer chip / chip shortage', '[{"en":"The new chip is much faster.","zh-TW":"新晶片快得多。"},{"en":"There''s a global chip shortage.","zh-TW":"全球有晶片短缺的問題。"}]', NULL, NULL, 1, 354),
(355, 'choir', '/kwaɪər/', 'noun', '{"zh-TW":["合唱團"],"en":["a group of people who sing together"]}', '{"root":{"text":"choir","meaning":"chorus (合唱)"},"logic":"源自拉丁語 chorus（合唱），指一群人一起歌唱。"}', 'church choir / join the choir', '[{"en":"She sings in the school choir.","zh-TW":"她在學校合唱團唱歌。"},{"en":"The choir performed at the concert hall.","zh-TW":"合唱團在音樂廳演出。"}]', NULL, NULL, 2, 355),
(356, 'choose', '/tʃuːz/', 'verb', '{"zh-TW":["選擇"],"en":["to pick from a number of options","to pick one from several options"]}', NULL, 'choose between / choose wisely', '[{"en":"You can choose any color you like.","zh-TW":"你可以選擇任何你喜歡的顏色。"},{"en":"They chose her as team leader.","zh-TW":"他們選她當組長。"},{"en":"You can choose any color.","zh-TW":"你可以選擇任何顏色。"},{"en":"Choose your words carefully.","zh-TW":"謹慎選擇你的用詞。"}]', '{"verb":"choose","noun":"choice","adjective":"chosen"}', NULL, 2, 356),
(357, 'church', '/tʃɜːrtʃ/', 'noun', '{"zh-TW":["教堂"],"en":["a building for Christian worship"]}', NULL, 'go to church / church service', '[{"en":"They go to church every Sunday.","zh-TW":"他們每個星期天去教堂。"},{"en":"The church was built in 1800.","zh-TW":"這座教堂建於1800年。"}]', NULL, NULL, 2, 357),
(358, 'circle', '/ˈsɜːrkəl/', 'noun', '{"zh-TW":["圓；圈子"],"en":["a round shape; a group of people"]}', NULL, 'full circle / inner circle', '[{"en":"Draw a circle on the paper.","zh-TW":"在紙上畫一個圓。"},{"en":"She has a wide circle of friends.","zh-TW":"她交友廣泛。"}]', '{"adjective":"circular"}', NULL, 2, 358),
(359, 'circuit', '/ˈsɜːrkɪt/', 'noun', '{"zh-TW":["電路；巡迴"],"en":["a roughly circular path or journey","an established route for events"]}', '{"root":{"text":"circ","meaning":"circle (圓)"},"suffix":{"text":"-uit","meaning":"going (去)"},"logic":"繞圈走，即「巡迴、電路」。"}', 'circuit board / short circuit / conference circuit', '[{"en":"A short circuit caused the power outage.","zh-TW":"短路導致了停電。"},{"en":"She''s well known on the conference circuit.","zh-TW":"她在會議巡迴圈中頗有名氣。"}]', NULL, NULL, 3, 359),
(360, 'circulate', '/ˈsɜːrkjʊleɪt/', 'verb', '{"zh-TW":["流通；散布"],"en":["to move continuously through a system","to pass from place to place"]}', '{"root":{"text":"circ","meaning":"circle (圓)"},"suffix":{"text":"-ulate","meaning":"to make (使)"},"logic":"使繞圈流動，即「流通」。"}', 'circulate a memo/report/document', '[{"en":"Please circulate the meeting minutes to all team members.","zh-TW":"請將會議記錄發送給所有團隊成員。"},{"en":"Rumors began to circulate about the merger.","zh-TW":"有關合併的傳言開始流傳。"}]', '{"noun":"circulation"}', NULL, 3, 360),
(361, 'circumstance', '/ˈsɜːrkəmstæns/', 'noun', '{"zh-TW":["情況；環境"],"en":["a fact or condition connected with an event","a condition or fact connected with an event"]}', '{"prefix":{"text":"circum-","meaning":"around (周圍)"},"root":{"text":"stance","meaning":"stand (站立)"},"logic":"站在周圍的事物，即「情況」。"}', 'under the circumstances / in certain circumstances; under the circumstances / financial circumstances', '[{"en":"Under the circumstances, we had no choice but to cancel.","zh-TW":"在這種情況下，我們別無選擇只能取消。"},{"en":"Economic circumstances forced a change in strategy.","zh-TW":"經濟情況迫使策略改變。"},{"en":"Under the circumstances, we had no choice.","zh-TW":"在那種情況下，我們別無選擇。"},{"en":"Their financial circumstances have improved.","zh-TW":"他們的經濟狀況有所改善。"}]', '{"adjective":"circumstantial"}', NULL, 4, 361),
(362, 'cite', '/saɪt/', 'verb', '{"zh-TW":["引用；舉例"],"en":["to quote as evidence or an example"]}', '{"root":{"text":"cit","meaning":"call/summon (召喚)"},"logic":"召喚證據，即「引用」。"}', 'cite a source/example/reason', '[{"en":"The report cites several studies as evidence.","zh-TW":"報告引用了多項研究作為證據。"},{"en":"She cited budget constraints as the main reason.","zh-TW":"她以預算限制作為主要原因。"}]', '{"noun":"citation"}', NULL, 1, 362),
(363, 'citizen', '/ˈsɪtɪzən/', 'noun', '{"zh-TW":["公民；市民"],"en":["a person who belongs to a country"]}', NULL, 'senior citizen / citizen rights', '[{"en":"She became a citizen last year.","zh-TW":"她去年成為了公民。"},{"en":"Every citizen has the right to vote.","zh-TW":"每位公民都有投票權。"}]', '{"noun2":"citizenship"}', NULL, 3, 363),
(364, 'city', '/ˈsɪti/', 'noun', '{"zh-TW":["城市"],"en":["a large town"]}', NULL, 'city center / city council', '[{"en":"The company is based in the city.","zh-TW":"公司設在城市裡。"},{"en":"The city council approved the project.","zh-TW":"市議會批准了這個專案。"}]', '{"noun":"city","adjective":"civic"}', NULL, 1, 364),
(365, 'claim', '/kleɪm/', 'verb', '{"zh-TW":["聲稱；索賠"],"en":["to state something as fact","to request something as one''s right","to say something is true; to ask for money"]}', '{"root":{"text":"claim","meaning":"cry out (喊出)"},"logic":"大聲喊出主張，即「聲稱」。"}', 'claim responsibility / insurance claim / claim that; claim that / insurance claim', '[{"en":"The company claims its product is the most efficient.","zh-TW":"公司聲稱其產品最有效率。"},{"en":"She filed an insurance claim for the damaged goods.","zh-TW":"她為受損商品提出了保險索賠。"},{"en":"He claims to be an expert.","zh-TW":"他聲稱自己是專家。"},{"en":"She filed an insurance claim.","zh-TW":"她提出了保險索賠。"}]', '{"noun":"claimant"}', NULL, 2, 365),
(366, 'clarify', '/ˈklærɪfaɪ/', 'verb', '{"zh-TW":["澄清；闡明"],"en":["to make something less confusing and more clear"]}', '{"root":{"text":"clar","meaning":"clear (清楚)"},"suffix":{"text":"-ify","meaning":"to make (使)"},"logic":"使清楚，即「澄清」。"}', 'clarify a point/issue/position', '[{"en":"Could you clarify what you mean by that statement?","zh-TW":"你能澄清那句話的意思嗎？"},{"en":"The spokesperson clarified the company''s position.","zh-TW":"發言人澄清了公司的立場。"}]', '{"noun":"clarification"}', NULL, 3, 366),
(367, 'class', '/klæs/', 'noun', '{"zh-TW":["班級；課程；階級"],"en":["a group of students; a lesson"]}', NULL, 'class room / first class', '[{"en":"I have English class at 10.","zh-TW":"我10點有英文課。"},{"en":"She graduated top of her class.","zh-TW":"她以班上第一名的成績畢業。"}]', '{"adjective":"classic","noun2":"classroom"}', NULL, 2, 367),
(368, 'classic', '/ˈklæsɪk/', 'adjective', '{"zh-TW":["經典的"],"en":["judged over time to be of the highest quality"]}', '{"root":{"text":"class","meaning":"class/rank (等級)"},"suffix":{"text":"-ic","meaning":"relating to (相關的)"},"logic":"屬於最高等級的，即「經典的」。"}', 'classic novel / classic design / a classic example', '[{"en":"This is a classic example of Art Deco architecture.","zh-TW":"這是裝飾藝術建築的經典範例。"},{"en":"She loves reading classic literature.","zh-TW":"她喜歡閱讀經典文學。"}]', '{"noun":"classic","adjective":"classical"}', NULL, 3, 368),
(369, 'classify', '/ˈklæsɪfaɪ/', 'verb', '{"zh-TW":["分類；歸類"],"en":["to arrange in categories or groups"]}', '{"root":{"text":"class","meaning":"class/group (類別)"},"suffix":{"text":"-ify","meaning":"to make (使)"},"logic":"使成為類別，即「分類」。"}', 'classify information/data/documents', '[{"en":"Products are classified by type and price range.","zh-TW":"產品按類型和價格範圍分類。"},{"en":"The documents were classified as confidential.","zh-TW":"文件被歸類為機密。"}]', '{"noun":"classification"}', NULL, 3, 369),
(370, 'classroom', '/ˈklæsruːm/', 'noun', '{"zh-TW":["教室"],"en":["a room where classes are taught"]}', NULL, 'in the classroom / classroom management', '[{"en":"The classroom was full of students.","zh-TW":"教室裡滿是學生。"},{"en":"Good classroom management is essential.","zh-TW":"良好的課堂管理很重要。"}]', NULL, NULL, 3, 370),
(371, 'clause', '/klɔːz/', 'noun', '{"zh-TW":["條款；子句"],"en":["a particular section of a legal document","a section of a legal document"]}', '{"root":{"text":"claus","meaning":"close (關閉)"},"logic":"關閉（完結）一個段落，即「條款」。"}', 'contract clause / penalty clause / escape clause; escape clause / confidentiality clause', '[{"en":"The penalty clause specifies damages for late delivery.","zh-TW":"罰款條款規定了延遲交付的賠償金。"},{"en":"Review all clauses carefully before signing.","zh-TW":"簽名前請仔細審閱所有條款。"},{"en":"Read every clause before signing.","zh-TW":"簽名前請閱讀每一條款。"},{"en":"The contract includes a termination clause.","zh-TW":"合同包含終止條款。"}]', NULL, NULL, 2, 371),
(372, 'clean', '/kliːn/', 'adjective', '{"zh-TW":["乾淨的；清潔","乾淨的"],"en":["free from dirt","to remove dirt"]}', NULL, 'clean energy / clean up; clean up / come clean', '[{"en":"We promote clean energy solutions.","zh-TW":"我們推廣潔淨能源方案。"},{"en":"Please clean up after the meeting.","zh-TW":"會議後請清理乾淨。"},{"en":"Keep your room clean.","zh-TW":"保持你的房間整潔。"},{"en":"He came clean about the mistake.","zh-TW":"他坦白了那個錯誤。"}]', '{"adjective":"clean","verb":"clean","noun":"cleaner","noun2":"cleanliness"}', NULL, 2, 372),
