(392, 'coincide', '/ˌkəʊɪnˈsaɪd/', 'verb', '{"zh-TW":["同時發生；巧合","巧合；同時發生"],"en":["to occur at the same time or place"]}', '{"prefix":{"text":"co-","meaning":"together (一起)"},"root":{"text":"incide","meaning":"fall upon (落入)"},"logic":"一起落入同一點，即「同時發生」。"}', 'coincide with / happen to coincide', '[{"en":"The product launch coincided with a major trade show.","zh-TW":"產品發布與一場大型貿易展同時舉行。"},{"en":"The meeting coincides with my vacation dates.","zh-TW":"會議與我的假期日期衝突。"},{"en":"My vacation coincides with the conference.","zh-TW":"我的假期和會議撞期。"},{"en":"The two events coincided by chance.","zh-TW":"兩件事巧合地同時發生。"}]', '{"noun":"coincidence","adjective":"coincidental"}', NULL, 3, 392),
(393, 'cold', '/koʊld/', 'adjective', '{"zh-TW":["冷的；冷淡的","冷的；感冒"],"en":["having a low temperature","unfriendly"]}', NULL, 'cold call / cold storage; catch a cold / cold weather', '[{"en":"Cold calling is part of sales training.","zh-TW":"電話開發是銷售訓練的一部分。"},{"en":"Keep the samples in cold storage.","zh-TW":"將樣品放在冷藏庫中。"},{"en":"It''s very cold outside.","zh-TW":"外面很冷。"},{"en":"She caught a cold last week.","zh-TW":"她上星期感冒了。"}]', '{"adjective":"cold","noun":"cold","adverb":"coldly"}', NULL, 1, 393),
(394, 'collaborate', '/kəˈlæbəreɪt/', 'verb', '{"zh-TW":["合作；協作"],"en":["to work jointly on an activity or project"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"labor","meaning":"work (工作)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起工作，即「合作」。"}', 'collaborate with / collaborate on a project', '[{"en":"The two companies collaborated on the research project.","zh-TW":"兩家公司在研究專案上合作。"},{"en":"Teams must collaborate effectively to meet deadlines.","zh-TW":"團隊必須有效合作以趕上截止日期。"}]', '{"noun":"collaboration","adjective":"collaborative"}', NULL, 4, 394),
(395, 'collapse', '/kəˈlæps/', 'verb', '{"zh-TW":["崩潰；倒塌","崩塌；倒下"],"en":["to fall down or give way suddenly","to fail suddenly and completely","to fall down suddenly","to fail completely"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"lapse","meaning":"fall (落下)"},"logic":"一起落下，即「崩潰」。"}', 'collapse of / market collapse / building collapse; collapse under pressure / building collapse', '[{"en":"The housing market collapsed during the financial crisis.","zh-TW":"房地產市場在金融危機期間崩盤。"},{"en":"Negotiations collapsed over pricing disagreements.","zh-TW":"談判因價格分歧而破裂。"},{"en":"The bridge collapsed during the earthquake.","zh-TW":"橋樑在地震中倒塌。"},{"en":"The company collapsed due to poor management.","zh-TW":"公司因管理不善而倒閉。"}]', '{"noun":"collapse"}', NULL, 3, 395),
