(397, 'collect', '/kəˈlekt/', 'verb', '{"zh-TW":["收集；收取"],"en":["to bring or gather together","to call for and receive payment"]}', '{"prefix":{"text":"col-","meaning":"together (一起)"},"root":{"text":"lect","meaning":"gather (聚集)"},"logic":"聚集在一起，即「收集」。"}', 'collect data/feedback/payment', '[{"en":"We collect customer feedback through surveys.","zh-TW":"我們透過調查收集客戶反饋。"},{"en":"The agency collects rent on behalf of landlords.","zh-TW":"代理機構代房東收取租金。"}]', '{"noun":"collection"}', NULL, 3, 397),
(398, 'college', '/ˈkɒlɪdʒ/', 'noun', '{"zh-TW":["大學；學院"],"en":["an institution for higher education"]}', NULL, 'go to college / college degree', '[{"en":"She went to college in Boston.","zh-TW":"她在波士頓上大學。"},{"en":"A college degree opens many doors.","zh-TW":"大學學位能開啟很多機會。"}]', NULL, NULL, 3, 398),
(399, 'color', '/ˈkʌlər/', 'noun', '{"zh-TW":["顏色"],"en":["the appearance of things resulting from light"]}', NULL, 'favorite color / color blind', '[{"en":"What''s your favorite color?","zh-TW":"你最喜歡什麼顏色？"},{"en":"The leaves change color in fall.","zh-TW":"秋天葉子會變色。"}]', '{"adjective":"colorful","verb":"color"}', NULL, 2, 399);